public class MainActivity extends Activity {
 private final int BG=0xff141414, PANEL=0xff181818, WHITE=0xffffffff, MUTED=0xffc5c5c5, RED=0xffe50914;
 private MovieBoxRepository api;
 private LinearLayout root, content, top;
 private ScrollView pageScroll;
 private JSONArray slides=new JSONArray();
 private int slideIndex=0;
 private final Handler handler=new Handler(Looper.getMainLooper());
 private Runnable slideTask;
 private TextView heroTitle,heroMeta,heroDesc;
 private ImageView heroImage;
 private FrameLayout heroFrame;
 private String detailPath="";
 private int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+.5f);}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setFlags(1024,1024);getWindow().getDecorView().setSystemUiVisibility(5894|1024|512);api=new MovieBoxRepository(this);buildShell();loadHome();}
 private GradientDrawable bg(int color,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(3));if(stroke!=0)d.setStroke(dp(2),stroke);return d;}
 private TextView txt(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(android.graphics.Typeface.DEFAULT,android.graphics.Typeface.BOLD);return t;}
 private void buildShell(){
  root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(BG);setContentView(root);
  top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.setPadding(dp(42),dp(8),dp(42),dp(8));top.setBackgroundColor(0xee141414);root.addView(top,new LinearLayout.LayoutParams(-1,dp(66)));
  TextView logo=txt("MOVIEBOX",25,RED,true);logo.setLetterSpacing(.06f);top.addView(logo,new LinearLayout.LayoutParams(dp(190),-2));
  View spacer=new View(this);top.addView(spacer,new LinearLayout.LayoutParams(0,1,1));
  nav("⌕  Search",()->showSearch(),false);nav("♡  My List",()->showSaved("mylist"),false);nav("◷  History",()->showSaved("history"),false);nav("⚙",()->showSettings(),false);
  pageScroll=new ScrollView(this);pageScroll.setFillViewport(false);pageScroll.setVerticalScrollBarEnabled(false);root.addView(pageScroll,new LinearLayout.LayoutParams(-1,0,1));
  content=new LinearLayout(this);content.setOrientation(1);content.setPadding(0,0,0,dp(55));pageScroll.addView(content);
 }
 private void nav(String label,Runnable action,boolean active){TextView v=txt(label,15,active?WHITE:0xffdddddd,active);v.setGravity(Gravity.CENTER);v.setPadding(dp(12),dp(10),dp(12),dp(10));v.setFocusable(true);v.setBackground(bg(active?0xff303030:0x00141414,0));v.setOnClickListener(w->action.run());v.setOnFocusChangeListener((w,f)->v.setBackground(bg(f?0xff3b3b3b:(active?0xff303030:0x00141414),f?WHITE:0)));top.addView(v,new LinearLayout.LayoutParams(-2,dp(46)));}
 private void runApi(java.util.concurrent.Callable<JSONObject> call,java.util.function.Consumer<JSONObject> done){content.removeAllViews();TextView loading=txt("Loading MovieBox…",20,WHITE,true);loading.setPadding(dp(50),dp(60),0,0);content.addView(loading);new Thread(()->{try{JSONObject j=call.call();runOnUiThread(()->done.accept(j));}catch(Exception e){runOnUiThread(()->showError(e));}}).start();}
 private void showError(Exception e){content.removeAllViews();TextView t=txt("MovieBox could not be loaded",24,WHITE,true);t.setPadding(dp(50),dp(50),0,dp(12));content.addView(t);TextView m=txt(String.valueOf(e.getMessage()),15,MUTED,false);m.setPadding(dp(50),0,dp(50),dp(20));content.addView(m);focusText("RETRY",()->loadHome());}
 private JSONObject merged(JSONObject o){JSONObject s=o==null?null:o.optJSONObject("subject");if(s==null)return o==null?new JSONObject():o;JSONObject n=new JSONObject();try{Iterator<String>it=s.keys();while(it.hasNext()){String k=it.next();n.put(k,s.get(k));}it=o.keys();while(it.hasNext()){String k=it.next();n.put(k,o.get(k));}}catch(Exception ignored){}return n;}
 private String id(JSONObject raw){JSONObject o=merged(raw);return o.optString("subjectId",o.optString("subject_id",o.optString("id","")));}
 private String title(JSONObject raw){JSONObject o=merged(raw);return o.optString("title",o.optString("name",o.optString("subjectName",o.optString("originalTitle","Untitled"))));}
 private String poster(JSONObject raw){JSONObject o=merged(raw);return pick(o,"coverVertical","verticalCover","poster","posterUrl","cover","coverUrl","image","thumbnail","pic","url","src");}
 private String backdrop(JSONObject raw){JSONObject o=merged(raw);String u=pick(raw,"image","banner","bannerImage","coverHorizontal","horizontalCover","backdrop","backdropUrl","url","src");if(u.isEmpty())u=pick(o,"coverHorizontal","horizontalCover","backdrop","backdropUrl","stills","cover","image","url","src");if(u.isEmpty())u=poster(raw);return u;}
 private String pick(JSONObject o,String...keys){if(o==null)return "";for(String k:keys){Object value=o.opt(k);String u=imageUrl(value);if(!u.isEmpty())return u;}return "";}
 private String imageUrl(Object value){if(value==null||value==JSONObject.NULL)return "";if(value instanceof String){String v=((String)value).trim();if(v.startsWith("//"))return "https:"+v;if(v.startsWith("http://")||v.startsWith("https://"))return v;return "";}if(value instanceof JSONObject){JSONObject j=(JSONObject)value;String[] keys={"url","src","imageUrl","fileUrl","path","original","large","medium","small","cover","image"};for(String k:keys){String u=imageUrl(j.opt(k));if(!u.isEmpty())return u;}}if(value instanceof JSONArray){JSONArray a=(JSONArray)value;for(int i=0;i<a.length();i++){String u=imageUrl(a.opt(i));if(!u.isEmpty())return u;}}return "";}
 private String year(JSONObject raw){String d=merged(raw).optString("releaseDate",merged(raw).optString("release_date",merged(raw).optString("year","")));java.util.regex.Matcher m=java.util.regex.Pattern.compile("(19|20)\\d{2}").matcher(d);return m.find()?m.group():"";}
 private String description(JSONObject raw){JSONObject o=merged(raw);return o.optString("description",o.optString("introduction",o.optString("overview","")));}
 private void loadHome(){if(slideTask!=null)handler.removeCallbacks(slideTask);runApi(()->api.home(),j->{content.removeAllViews();JSONObject data=j.optJSONObject("data");JSONArray ops=data==null?null:data.optJSONArray("operatingList");if(ops==null){showError(new Exception("Home feed missing operatingList"));return;}slides=new JSONArray();for(int oi=0;oi<ops.length();oi++){JSONObject op=ops.optJSONObject(oi);if(op==null)continue;JSONObject banner=op.optJSONObject("banner");JSONArray raw=banner==null?null:banner.optJSONArray("items");if(raw==null)raw=op.optJSONArray("bannerItems");if(raw==null)raw=op.optJSONArray("banners");if(raw!=null)for(int k=0;k<raw.length()&&slides.length()<7;k++){JSONObject item=raw.optJSONObject(k);if(item!=null&&(!backdrop(item).isEmpty()||!poster(item).isEmpty()))slides.put(item);}if(slides.length()>=7)break;}if(slides.length()>0)addHero();for(int i=0;i<ops.length();i++){JSONObject op=ops.optJSONObject(i);if(op==null)continue;JSONArray a=op.optJSONArray("subjects");if(a==null||a.length()==0)continue;String heading=op.optString("title",op.optString("name",op.optString("subjectTitle",op.optString("label","Recommended"))));addSection(heading,a);}if(content.getChildCount()==0)content.addView(txt("No MovieBox titles available.",20,WHITE,true));});}
 private void addHero(){slideIndex=0;heroFrame=new FrameLayout(this);heroFrame.setBackgroundColor(PANEL);content.addView(heroFrame,new LinearLayout.LayoutParams(-1,dp(430)));heroImage=new ImageView(this);heroImage.setScaleType(ImageView.ScaleType.CENTER_CROP);heroFrame.addView(heroImage,new FrameLayout.LayoutParams(-1,-1));View shade=new View(this);shade.setBackground(new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,new int[]{0xf0000000,0x99000000,0x00000000}));heroFrame.addView(shade,new FrameLayout.LayoutParams(-1,-1));LinearLayout bottomShade=new LinearLayout(this);bottomShade.setOrientation(1);bottomShade.setPadding(dp(54),0,dp(54),dp(42));bottomShade.setGravity(Gravity.BOTTOM);bottomShade.setBackground(new GradientDrawable(GradientDrawable.Orientation.BOTTOM_TOP,new int[]{0xee141414,0x00141414}));heroFrame.addView(bottomShade,new FrameLayout.LayoutParams(-1,-1));heroTitle=txt("",38,WHITE,true);heroTitle.setMaxLines(2);heroTitle.setEllipsize(TextUtils.TruncateAt.END);bottomShade.addView(heroTitle);heroMeta=txt("",14,0xff46d369,true);LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(-1,-2);mp.topMargin=dp(10);bottomShade.addView(heroMeta,mp);heroDesc=txt("",16,WHITE,false);heroDesc.setMaxLines(3);heroDesc.setEllipsize(TextUtils.TruncateAt.END);LinearLayout.LayoutParams dpv=new LinearLayout.LayoutParams(dp(610),-2);dpv.topMargin=dp(10);bottomShade.addView(heroDesc,dpv);LinearLayout actions=new LinearLayout(this);actions.setGravity(Gravity.CENTER_VERTICAL);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,dp(52));ap.topMargin=dp(18);bottomShade.addView(actions,ap);TextView watch=button("▶  WATCH",true,()->{JSONObject o=slides.optJSONObject(slideIndex);if(o!=null)openDetail(id(o));});actions.addView(watch,new LinearLayout.LayoutParams(dp(170),dp(48)));TextView more=button("ⓘ  MORE INFO",false,()->{JSONObject o=slides.optJSONObject(slideIndex);if(o!=null)openDetail(id(o));});LinearLayout.LayoutParams moreLp=new LinearLayout.LayoutParams(dp(180),dp(48));moreLp.leftMargin=dp(12);actions.addView(more,moreLp);LinearLayout dots=new LinearLayout(this);dots.setGravity(Gravity.CENTER);FrameLayout.LayoutParams dotLp=new FrameLayout.LayoutParams(-2,dp(30),Gravity.RIGHT|Gravity.BOTTOM);dotLp.setMargins(0,0,dp(50),dp(18));heroFrame.addView(dots,dotLp);for(int i=0;i<slides.length();i++){final int ix=i;TextView dot=txt("●",13,i==0?RED:0xffaaaaaa,true);dot.setPadding(dp(5),dp(4),dp(5),dp(4));dot.setFocusable(true);dot.setOnClickListener(v->setSlide(ix));dots.addView(dot);}setSlide(0);slideTask=()->{if(slides.length()>1){setSlide((slideIndex+1)%slides.length());handler.postDelayed(slideTask,7000);}};if(slides.length()>1)handler.postDelayed(slideTask,7000);}
 private TextView button(String label,boolean primary,Runnable run){TextView b=txt(label,16,primary?0xff000000:WHITE,true);b.setGravity(Gravity.CENTER);b.setFocusable(true);b.setBackground(bg(primary?WHITE:0x99555555,0));b.setOnFocusChangeListener((v,f)->b.setBackground(bg(f?0xffdddddd:(primary?WHITE:0x99555555),f?RED:0)));b.setOnClickListener(v->run.run());return b;}
 private void setSlide(int i){if(slides.length()==0)return;slideIndex=Math.max(0,Math.min(i,slides.length()-1));JSONObject o=slides.optJSONObject(slideIndex);String image=backdrop(o);if(image.isEmpty())image=poster(o);Glide.with(this).load(image).centerCrop().into(heroImage);heroTitle.setText(title(o));String y=year(o),rating=merged(o).optString("imdbRatingValue","");heroMeta.setText((rating.isEmpty()?"Featured":rating+" ★")+"    "+(y.isEmpty()?"":y+"    ")+"HD");heroDesc.setText(description(o));}
 private void addSection(String heading,JSONArray items){TextView h=txt(heading,20,0xffe5e5e5,true);h.setPadding(dp(24),dp(24),dp(24),dp(8));content.addView(h);int count=items.length(),cols=10;int screenDp=(int)(getResources().getDisplayMetrics().widthPixels/getResources().getDisplayMetrics().density);int horizontal=dp(48),gap=dp(8);int cardW=Math.max(dp(72),(getResources().getDisplayMetrics().widthPixels-horizontal-gap*(cols-1))/cols);int rows=(count+cols-1)/cols;int index=0;for(int r=0;r<rows;r++){LinearLayout line=new LinearLayout(this);line.setOrientation(0);line.setGravity(Gravity.TOP);line.setPadding(dp(24),dp(8),dp(24),dp(8));content.addView(line,new LinearLayout.LayoutParams(-1,-2));for(int c=0;c<cols&&index<count;c++,index++){JSONObject o=items.optJSONObject(index);if(o!=null)addCard(line,o,cardW,gap);}}}
 private void addCard(LinearLayout line,JSONObject o,int width,int gap){LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setFocusable(true);card.setFocusableInTouchMode(false);card.setClickable(true);card.setDescendantFocusability(ViewGroup.FOCUS_BLOCK_DESCENDANTS);card.setPadding(dp(2),dp(2),dp(2),dp(4));card.setBackground(bg(PANEL,0));card.setClipChildren(false);card.setClipToPadding(false);ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackgroundColor(0xff252525);card.addView(image,new LinearLayout.LayoutParams(width,(int)(width*1.5f)));String p=poster(o);if(!p.isEmpty())Glide.with(this).load(p).placeholder(new android.graphics.drawable.ColorDrawable(0xff252525)).error(new android.graphics.drawable.ColorDrawable(0xff333333)).centerCrop().into(image);else{TextView fallback=txt("NO IMAGE",10,MUTED,true);fallback.setGravity(Gravity.CENTER);card.addView(fallback,new LinearLayout.LayoutParams(width,(int)(width*1.5f)));}TextView name=txt(title(o),12,WHITE,true);name.setMaxLines(1);name.setEllipsize(TextUtils.TruncateAt.END);name.setPadding(dp(3),dp(5),dp(3),0);card.addView(name);TextView yr=txt(year(o),10,MUTED,false);yr.setPadding(dp(3),0,dp(3),0);card.addView(yr);card.setOnFocusChangeListener((v,f)->{card.animate().scaleX(f?1.12f:1f).scaleY(f?1.12f:1f).setDuration(130).start();card.setElevation(f?dp(18):0);card.setBackground(bg(f?0xff303030:PANEL,f?WHITE:0));if(f){card.bringToFront();line.invalidate();}});card.setOnClickListener(v->openDetail(id(o)));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(width,-2);lp.rightMargin=gap;line.addView(card,lp);}
 private void focusText(String s,Runnable r){TextView v=txt(s,16,RED,true);v.setPadding(dp(50),dp(18),dp(50),dp(18));v.setFocusable(true);v.setOnClickListener(w->r.run());content.addView(v);}
 private void showSearch(){content.removeAllViews();TextView h=txt("Search Movies & Series",28,WHITE,true);h.setPadding(dp(50),dp(35),0,dp(20));content.addView(h);EditText input=new EditText(this);input.setSingleLine(true);input.setTextColor(WHITE);input.setHintTextColor(MUTED);input.setHint("Search MovieBox…");input.setTextSize(18);input.setPadding(dp(18),0,dp(18),0);input.setBackground(bg(PANEL,0xff555555));LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(dp(720),dp(58));ip.leftMargin=dp(50);content.addView(input,ip);focusText("SEARCH",()->search(input.getText().toString()));input.setOnEditorActionListener((v,a,e)->{search(input.getText().toString());return true;});input.requestFocus();}
 private void search(String q){if(q.trim().isEmpty())return;runApi(()->api.search(q,1),j->{content.removeAllViews();TextView h=txt("Results for: "+q,24,WHITE,true);h.setPadding(dp(48),dp(28),0,dp(10));content.addView(h);JSONObject d=j.optJSONObject("data");JSONArray a=d==null?null:d.optJSONArray("subjects");if(a==null&&d!=null)a=d.optJSONArray("items");if(a!=null)addSection("Search results",a);});}
 private void openDetail(String subjectId){if(subjectId.isEmpty())return;runApi(()->api.detail(subjectId),j->{content.removeAllViews();JSONObject data=j.optJSONObject("data");if(data==null)data=new JSONObject();JSONObject subject=data.optJSONObject("subject");if(subject==null)subject=data;detailPath=subject.optString("detailPath","");String name=title(subject);addHeroDetail(subject);TextView synopsis=txt("SYNOPSIS",18,WHITE,true);synopsis.setPadding(dp(50),dp(25),0,dp(8));content.addView(synopsis);TextView desc=txt(description(subject),15,MUTED,false);desc.setPadding(dp(50),0,dp(50),dp(20));content.addView(desc);focusText("▶  PLAY",()->launchPlayer(subjectId,name,detailPath,0,0));JSONObject resource=data.optJSONObject("resource");JSONArray seasons=resource==null?null:resource.optJSONArray("seasons");if(seasons!=null)for(int si=0;si<seasons.length();si++){JSONObject season=seasons.optJSONObject(si);if(season==null)continue;JSONArray eps=season.optJSONArray("episodes");if(eps!=null)addSection("Season "+season.optString("se",""+(si+1)),eps);}});}
 private void addHeroDetail(JSONObject o){FrameLayout f=new FrameLayout(this);content.addView(f,new LinearLayout.LayoutParams(-1,dp(340)));ImageView im=new ImageView(this);im.setScaleType(ImageView.ScaleType.CENTER_CROP);f.addView(im,new FrameLayout.LayoutParams(-1,-1));String u=backdrop(o);if(u.isEmpty())u=poster(o);Glide.with(this).load(u).centerCrop().into(im);TextView t=txt(title(o),32,WHITE,true);t.setGravity(Gravity.BOTTOM);t.setPadding(dp(50),0,0,dp(32));t.setBackground(new GradientDrawable(GradientDrawable.Orientation.BOTTOM_TOP,new int[]{0xee141414,0x00141414}));f.addView(t,new FrameLayout.LayoutParams(-1,-1));}
 private void launchPlayer(String id,String name,String path,int season,int episode){Intent i=new Intent(this,PlayerActivity.class);i.putExtra("movieBox",true);i.putExtra("subjectId",id);i.putExtra("detailPath",path);i.putExtra("token",api.token());i.putExtra("season",season);i.putExtra("episode",episode);i.putExtra("title",name);startActivity(i);}
 private void showSaved(String key){content.removeAllViews();TextView h=txt(key.equals("mylist")?"My List":"Watch History",26,WHITE,true);h.setPadding(dp(48),dp(30),0,0);content.addView(h);content.addView(txt("Your saved titles will appear here.",16,MUTED,false));}
 private void showSettings(){new AlertDialog.Builder(this).setTitle("Playback server").setMessage("MovieBox playback is connected to the same MovieBox service used by the web app.").setPositiveButton("OK",null).show();}
 @Override public void onBackPressed(){if(slideTask!=null)handler.removeCallbacks(slideTask);loadHome();}
 @Override protected void onDestroy(){super.onDestroy();if(slideTask!=null)handler.removeCallbacks(slideTask);}
}